/**
 * Return the full evolution line for a species, from base form to final stage.
 * e.g. getFullEvoLine(12) → [10, 11, 12] (Caterpie → Metapod → Butterfree)
 */
export function getFullEvoLine(speciesId) {
  // Walk backwards to find the base form
  let base = speciesId;
  const visited = new Set();
  while (PRE_EVOLUTIONS[base] != null && !visited.has(base)) {
    visited.add(base);
    base = PRE_EVOLUTIONS[base];
  }
  // Walk forwards collecting the entire tree (BFS)
  const line = [base];
  const queue = [base];
  while (queue.length) {
    const cur = queue.shift();
    const children = EVOLUTIONS[cur];
    if (children) {
      for (const c of children) {
        if (!line.includes(c.evo)) {
          line.push(c.evo);
          queue.push(c.evo);
        }
      }
    }
  }
  return line;
}

/**
 * Walk the pre-evolution chain to find the closest ancestor (or self)
 * that has wild encounter data.  Returns the ancestor species ID, or null.
 */
export function getWildAncestor(speciesId, wildEncounters) {
  let cur = speciesId;
  const visited = new Set();
  while (cur != null && !visited.has(cur)) {
    if (wildEncounters[cur]) return cur;
    visited.add(cur);
    cur = PRE_EVOLUTIONS[cur] ?? null;
  }
  return null;
}

/**
 * Build a Set of all species reachable by evolving any species in wildEncounters.
 * Includes the wild species themselves AND all their evolutions.
 */
export function buildWildWithEvolutions(wildEncounters) {
  const result = new Set();
  for (const idStr of Object.keys(wildEncounters)) {
    const id = Number(idStr);
    // Add the base wild species
    result.add(id);
    // Add all evolutions (recursively)
    const queue = [id];
    while (queue.length) {
      const cur = queue.shift();
      const children = EVOLUTIONS[cur];
      if (children) {
        for (const c of children) {
          if (!result.has(c.evo)) {
            result.add(c.evo);
            queue.push(c.evo);
          }
        }
      }
    }
  }
  return result;
}

